<style>
    /* Ces styles isolés donnent au rapport l'apparence d'un document administratif A4. */
    .administrative-document { max-width: 920px; margin: 0 auto; padding: 48px 54px; color: #1d2419; background: #fff; border: 1px solid #d8d3c9; font-family: Arial, sans-serif; font-size: 14px; line-height: 1.55; }
    .administrative-document__header { display: table; width: 100%; padding-bottom: 18px; border-bottom: 3px solid #31380f; }
    .administrative-document__brand, .administrative-document__identity { display: table-cell; vertical-align: middle; }
    .administrative-document__brand { width: 66%; }
    .administrative-document__brand img { width: 72px; height: auto; vertical-align: middle; margin-right: 15px; }
    .administrative-document__brand-copy { display: inline-block; vertical-align: middle; }
    .administrative-document__brand h1 { margin: 0; color: #14202b; font-size: 25px; letter-spacing: .04em; }
    .administrative-document__brand p, .administrative-document__identity p { margin: 2px 0; }
    .administrative-document__identity { text-align: right; font-size: 12px; }
    .administrative-document__title { margin: 38px 0 8px; text-align: center; color: #14202b; font-size: 21px; text-transform: uppercase; }
    .administrative-document__reference { margin: 0 0 30px; text-align: center; font-size: 12px; }
    .administrative-document__meta { width: 100%; margin-bottom: 28px; border-collapse: collapse; }
    .administrative-document__meta th, .administrative-document__meta td { padding: 7px 9px; text-align: left; border: 1px solid #bfc3b1; }
    .administrative-document__meta th { width: 22%; color: #31380f; background: #edede5; }
    .administrative-document__purpose { margin: 0 0 26px; text-align: justify; }
    .administrative-section { margin-top: 27px; page-break-inside: auto; }
    .administrative-section h2 { margin: 0 0 10px; padding-bottom: 5px; color: #31380f; border-bottom: 1px solid #798057; font-size: 16px; }
    .administrative-section p { margin: 8px 0; text-align: justify; }
    .administrative-metrics, .administrative-table { width: 100%; margin: 13px 0 18px; border-collapse: collapse; font-size: 12px; }
    .administrative-metrics th, .administrative-metrics td, .administrative-table th, .administrative-table td { padding: 7px 8px; border: 1px solid #c9cbbb; vertical-align: top; }
    .administrative-metrics th, .administrative-table th { color: #20280b; background: #edede5; font-weight: 700; text-align: left; }
    .administrative-metrics th { width: 55%; }
    .administrative-table caption { padding: 0 0 6px; color: #14202b; font-weight: 700; text-align: left; }
    .administrative-empty { color: #65695e; font-style: italic; text-align: center; }
    .administrative-signatures { display: table; width: 100%; margin-top: 55px; page-break-inside: avoid; }
    .administrative-signatures div { display: table-cell; width: 50%; height: 85px; text-align: center; vertical-align: top; }
    .administrative-signatures strong { display: block; border-top: 1px solid #73776b; padding-top: 7px; margin: 58px 24px 0; }
    .administrative-footer { margin-top: 26px; padding-top: 8px; border-top: 1px solid #c9cbbb; color: #6c7065; font-size: 10px; text-align: center; }
    @media (max-width: 767px) { .administrative-document { padding: 28px 20px; } .administrative-document__brand, .administrative-document__identity { display: block; width: 100%; text-align: left; } .administrative-document__identity { margin-top: 12px; } }
    @media print { .administrative-document { max-width: none; padding: 0; border: 0; } }
</style>
